  'home.procEyebrow':                 { sk: "[ 03 — PROCESS ]", cs: "[ 03 — PROCESS ]", hu: "[ 03 — FOLYAMAT ]", en: "[ 03 — PROCESS ]", de: "[ 03 — PROZESS ]" },
  'home.procTitle':                   { sk: "Ako s nami spolupracujete", cs: "Jak s námi spolupracujete", hu: "Hogyan dolgozunk Önökkel", en: "How you work with us", de: "Wie Sie mit uns zusammenarbeiten" },
  'home.procLead':                    { sk: "Transparentný proces bez skrytých krokov. Viete, čo sa deje, každý týždeň.", cs: "Transparentní proces bez skrytých kroků. Víte, co se děje, každý týden.", hu: "Átlátható folyamat rejtett lépések nélkül. Tudják, mi történik minden héten.", en: "Transparent process with no hidden steps. You know what's happening every week.", de: "Transparenter Prozess ohne versteckte Schritte. Sie wissen jede Woche, was passiert." },
  'home.proc1Title':                  { sk: "Audit a stratégia", cs: "Audit a strategie", hu: "Audit és stratégia", en: "Audit and strategy", de: "Audit und Strategie" },
  'home.proc1Desc':                   { sk: "Prejdeme si váš biznis, čísla a konkurenciu. Dostanete plán s jasnými cieľmi.", cs: "Projdeme si váš byznys, čísla a konkurenci. Dostanete plán s jasnými cíli.", hu: "Áttekintjük az üzletüket, számokat és versenytársakat. Világos célokkal rendelkező tervet kapnak.", en: "We review your business, numbers and competition. You get a plan with clear objectives.", de: "Wir gehen Ihr Business, Zahlen und Konkurrenz durch. Sie erhalten einen Plan mit klaren Zielen." },
  'home.proc2Title':                  { sk: "Setup a spustenie", cs: "Setup a spuštění", hu: "Beállítás és indítás", en: "Setup and launch", de: "Setup und Start" },
  'home.proc2Desc':                   { sk: "Nastavíme meranie, kampane a kreatívy. Do 14 dní beží prvá kampaň.", cs: "Nastavíme měření, kampaně a kreativy. Do 14 dnů běží první kampaň.", hu: "Beállítjuk a mérést, kampányokat és kreatívokat. 14 napon belül fut az első kampány.", en: "We set up tracking, campaigns and creatives. First campaign runs within 14 days.", de: "Wir richten Tracking, Kampagnen und Kreative ein. Binnen 14 Tagen läuft die erste Kampagne." },
  'home.proc3Title':                  { sk: "Optimalizácia", cs: "Optimalizace", hu: "Optimalizálás", en: "Optimisation", de: "Optimierung" },
  'home.proc3Desc':                   { sk: "Týždenné reporty, A/B testy, škálovanie toho, čo funguje.", cs: "Týdenní reporty, A/B testy, škálování toho, co funguje.", hu: "Heti riportok, A/B tesztek, a működő elemek skálázása.", en: "Weekly reports, A/B tests, scaling what works.", de: "Wöchentliche Reports, A/B Tests, Skalierung dessen, was funktioniert." },
  'home.proc4Title':                  { sk: "Rast", cs: "Růst", hu: "Növekedés", en: "Growth", de: "Wachstum" },
  'home.proc4Desc':                   { sk: "Mesačné review, nové kanály, scaling budgetu podľa reálneho ROI.", cs: "Měsíční review, nové kanály, scaling rozpočtu podle reálného ROI.", hu: "Havi értékelés, új csatornák, a költségvetés skálázása a valós ROI alapján.", en: "Monthly review, new channels, budget scaling based on real ROI.", de: "Monatliches Review, neue Kanäle, Skalierung des Budgets basierend auf echtem ROI." },
  'home.calcEyebrow':                 { sk: "[ 04 — CALCULATOR ]", cs: "[ 04 — CALCULATOR ]", hu: "[ 04 — KALKULÁTOR ]", en: "[ 04 — CALCULATOR ]", de: "[ 04 — CALCULATOR ]" },
  'home.calcTitle':                   { sk: "Koľko môžete získať?", cs: "Kolik můžete získat?", hu: "Mennyit nyerhet?", en: "How much can you gain?", de: "Wie viel können Sie gewinnen?" },
  'home.calcLead':                    { sk: "Rýchly odhad na základe reálnych dát našich klientov. Nie záruka — odrazový mostík.", cs: "Rychlý odhad na základě reálných dat našich klientů. Není zárukou — odrazový můstek.", hu: "Gyors becslés ügyfeleink valós adatai alapján. Nem garancia — kiindulópont.", en: "Quick estimate based on real data from our clients. Not a guarantee — a starting point.", de: "Schnelle Schätzung basierend auf echten Daten unserer Kunden. Keine Garantie — ein Ausgangspunkt." },
  'home.calcBudget':                  { sk: "Mesačný budget na reklamu", cs: "Měsíční rozpočet na reklamu", hu: "Havi hirdetési költségvetés", en: "Monthly advertising budget", de: "Monatliches Werbebudget" },
  'home.calcAov':                     { sk: "Priemerná hodnota objednávky", cs: "Průměrná hodnota objednávky", hu: "Átlagos rendelési érték", en: "Average order value", de: "Durchschnittlicher Bestellwert" },
  'home.calcCr':                      { sk: "Koľko návštevníkov u vás kupuje", cs: "Kolik návštevníků u vás nakupuje", hu: "Hány látogató vásárol Önnél", en: "How many visitors make purchases", de: "Wie viele Besucher kaufen bei Ihnen" },
  'home.calcNote':                    { sk: "Odhad podľa benchmarkov z odvetvia. Predpokladáme bežnú cenu za klik €0,55. Skutočné výsledky závisia od konkurencie a kvality kampane.", cs: "Odhad podle benchmarků z odvětví. Předpokládáme běžnou cenu za klik €0,55. Skutečné výsledky závisí na konkurenci a kvalitě kampaně.", hu: "Becslés ágazati benchmarkok alapján. Átlagos €0,55-ös kattintási költséget feltételezünk. A tényleges eredmények a versenytől és a kampány minőségétől függnek.", en: "Estimate based on industry benchmarks. We assume standard cost per click €0.55. Actual results depend on competition and campaign quality.", de: "Schätzung basierend auf Branchen-Benchmarks. Wir nehmen einen üblichen Klickpreis von €0,55 an. Die tatsächlichen Ergebnisse hängen von der Konkurrenz und der Kampagnenqualität ab." },
  'home.calcRevenueLabel':            { sk: "Odhadované mesačné tržby", cs: "Odhadované měsíční tržby", hu: "Becsült havi bevétel", en: "Estimated monthly revenue", de: "Geschätzter monatlicher Umsatz" },
  'home.calcUpliftLabel':             { sk: "Potenciálny nárast", cs: "Potenciální nárůst", hu: "Potenciális növekedés", en: "Potential increase", de: "Potentielle Steigerung" },
  'home.calcOrdersLabel':             { sk: "Objednávok / mesiac", cs: "Objednávek / měsíc", hu: "Rendelések / hónap", en: "Orders / month", de: "Bestellungen / Monat" },
  'home.calcCta':                     { sk: "Chcem presný plán", cs: "Chci přesný plán", hu: "Pontos tervet kérek", en: "I want a precise plan", de: "Ich möchte einen genauen Plan" },
  'home.contactEyebrow':              { sk: "[ 07 — CONTACT ]", cs: "[ 07 — CONTACT ]", hu: "[ 07 — KAPCSOLAT ]", en: "[ 07 — CONTACT ]", de: "[ 07 — CONTACT ]" },
  'home.contactResponsePill':         { sk: "Priemerná odpoveď · 4 hod", cs: "Průměrná odpověď · 4 hod", hu: "Átlagos válaszidő · 4 óra", en: "Average response · 4 hrs", de: "Durchschnittliche Antwort · 4 Std" },
  'home.contactH1Prefix':             { sk: "Poďme si dohodnúť", cs: "Pojďme si domluvit", hu: "Beszéljük meg az", en: "Let's arrange an", de: "Vereinbaren wir ein" },
  'home.contactH1Highlight':          { sk: "audit.", cs: "audit.", hu: "auditet.", en: "audit.", de: "Audit." },
  'home.contactLead':                 { sk: "30 minút, bez záväzku. Prejdeme vaše účty, meranie a ukážeme, kde utekajú peniaze.", cs: "30 minut, bez závazku. Projdeme vaše účty, měření a ukážeme, kde utíkají peníze.", hu: "30 perc, kötelezettség nélkül. Átnézzük fiókjait, a mérését és megmutatjuk, hol vesznek el a pénzek.", en: "30 minutes, no obligation. We'll review your accounts, tracking and show where money is being wasted.", de: "30 Minuten, unverbindlich. Wir durchleuchten Ihre Accounts, Messungen und zeigen, wo Geld verloren geht." },
