  'home.ctaMainTitle':                { sk: "Otvoriť formulár a napísať nám za 60 sekúnd", cs: "Otevřít formulář a napsat nám za 60 sekund", hu: "Nyissa meg az űrlapot és írjon nekünk 60 másodperc alatt", en: "Open the form and write to us in 60 seconds", de: "Formular öffnen und uns in 60 Sekunden schreiben" },
  'home.ctaSlotsLeft':                { sk: "voľná konzultácia tento týždeň", cs: "volná konzultace tento týden", hu: "ingyenes konzultáció ezen a héten", en: "free consultation this week", de: "kostenlose Beratung diese Woche" },
