  'contactSection.responsePill':            { sk: "Priemerná odpoveď · 4 hod", cs: "Průměrná odpověď · 4 hod", hu: "Átlagos válaszidő · 4 óra", en: "Average response · 4 hours", de: "Durchschnittliche Antwort · 4 Std" },
  'contactSection.titlePrefix':             { sk: "Poďme si dohodnúť", cs: "Pojďme si domluvit", hu: "Beszéljük meg", en: "Let's arrange a", de: "Lassen Sie uns vereinbaren" },
  'contactSection.lead':                    { sk: "30 minút, bez záväzku. Prejdeme vaše účty, meranie a ukážeme, kde utekajú peniaze.", cs: "30 minut, bez závazku. Projdeme vaše účty, měření a ukážeme, kde utíkají peníze.", hu: "30 perc, kötelezettség nélkül. Átnézzük a fiókjait, a mérést és megmutatjuk, hol folynak el a pénzek.", en: "30 minutes, no obligation. We'll review your accounts, measurement and show where money is being wasted.", de: "30 Minuten, unverbindlich. Wir gehen Ihre Konten und Messungen durch und zeigen, wo Geld verschwendet wird." },
  'contactSection.ctaEyebrow':              { sk: "[ Začnime jednoducho ]", cs: "[ Začněme jednoduše ]", hu: "[ Kezdjük egyszerűen ]", en: "[ Let's start simply ]", de: "[ Fangen wir einfach an ]" },
  'contactSection.ctaTitle':                { sk: "Otvoriť formulár a napísať nám za 60 sekúnd", cs: "Otevřít formulář a napsat nám za 60 sekund", hu: "Nyissa meg az űrlapot és írjon nekünk 60 másodperc alatt", en: "Open form and message us in 60 seconds", de: "Formular öffnen und uns in 60 Sekunden schreiben" },
  'contactSection.ctaNote':                 { sk: "Bezplatný audit · bez záväzku", cs: "Bezplatný audit · bez závazku", hu: "Ingyenes audit · kötelezettség nélkül", en: "Free audit · no obligation", de: "Kostenloser Audit · unverbindlich" },
  'contactSection.channelEmail':            { sk: "E-mail", cs: "E-mail", hu: "E-mail", en: "Email", de: "E-Mail" },
