  'tools.t1.4what':                  { sk: "Drahší kanál, ale presné cielenie podľa pozície, firmy, veľkosti.", cs: "Drahší kanál, ale presné cielenie podľa pozície, firmy, veľkosti.", hu: "Drahší kanál, ale presné cielenie podľa pozície, firmy, veľkosti.", en: "More expensive channel, but precise targeting by position, company, size.", de: "Drahší kanál, ale presné cielenie podľa pozície, firmy, veľkosti." },
  'tools.t1.5when':                  { sk: "Pri B2B a 40+ cieľovkách.", cs: "Pri B2B a 40+ cieľovkách.", hu: "Pri B2B a 40+ cieľovkách.", en: "For B2B and 40+ target groups.", de: "Pri B2B a 40+ cieľovkách." },
  'tools.t1.5what':                  { sk: "Často 30-50 % nižší CPC než Google. Často podceňované, ale stojí za test.", cs: "Často 30-50 % nižší CPC než Google. Často podceňované, ale stojí za test.", hu: "Často 30-50 % nižší CPC než Google. Často podceňované, ale stojí za test.", en: "Often 30-50% lower CPC than Google. Often underestimated, but worth testing.", de: "Často 30-50 % nižší CPC než Google. Často podceňované, ale stojí za test." },
  'tools.cat2Title':                 { sk: "Meranie a analytika", cs: "Meranie a analytika", hu: "Meranie a analytika", en: "Measurement and analytics", de: "Meranie a analytika" },
  'tools.cat2Desc':                  { sk: "Bez merania nie je optimalizácie. Toto je kritická základná vrstva.", cs: "Bez merania nie je optimalizácie. Toto je kritická základná vrstva.", hu: "Bez merania nie je optimalizácie. Toto je kritická základná vrstva.", en: "Without measurement there's no optimization. This is the critical foundation layer.", de: "Bez merania nie je optimalizácie. Toto je kritická základná vrstva." },
  'tools.t2.1when':                  { sk: "Vždy, povinný základ.", cs: "Vždy, povinný základ.", hu: "Vždy, povinný základ.", en: "Always, mandatory foundation.", de: "Vždy, povinný základ." },
  'tools.t2.1what':                  { sk: "Sledovanie návštev, konverzií, atribúcie. Konfigurujeme udalosti vrátane custom eventov.", cs: "Sledovanie návštev, konverzií, atribúcie. Konfigurujeme udalosti vrátane custom eventov.", hu: "Sledovanie návštev, konverzií, atribúcie. Konfigurujeme udalosti vrátane custom eventov.", en: "Tracking visits, conversions, attribution. We configure events including custom events.", de: "Sledovanie návštev, konverzií, atribúcie. Konfigurujeme udalosti vrátane custom eventov." },
  'tools.t2.2when':                  { sk: "Pri každom novom klientovi.", cs: "Pri každom novom klientovi.", hu: "Pri každom novom klientovi.", en: "For every new client.", de: "Pri každom novom klientovi." },
  'tools.t2.2what':                  { sk: "Centrálny manažment všetkých trackingových kódov. Žiadne ručné editovanie webu.", cs: "Centrálny manažment všetkých trackingových kódov. Žiadne ručné editovanie webu.", hu: "Centrálny manažment všetkých trackingových kódov. Žiadne ručné editovanie webu.", en: "Central management of all tracking codes. No manual website editing.", de: "Centrálny manažment všetkých trackingových kódov. Žiadne ručné editovanie webu." },
  'tools.t2.3when':                  { sk: "Pri väčších rozpočtoch (€2k+/mes).", cs: "Pri väčších rozpočtoch (€2k+/mes).", hu: "Pri väčších rozpočtoch (€2k+/mes).", en: "For larger budgets (€2k+/month).", de: "Pri väčších rozpočtoch (€2k+/mes)." },
  'tools.t2.3what':                  { sk: "Obísť iOS 14.5+ a ad-blockery. Dáta idú cez náš server priamo platformám.", cs: "Obísť iOS 14.5+ a ad-blockery. Dáta idú cez náš server priamo platformám.", hu: "Obísť iOS 14.5+ a ad-blockery. Dáta idú cez náš server priamo platformám.", en: "Bypass iOS 14.5+ and ad-blockers. Data goes through our server directly to platforms.", de: "Obísť iOS 14.5+ a ad-blockery. Dáta idú cez náš server priamo platformám." },
  'tools.t2.4when':                  { sk: "Vždy, ak používame Meta Ads.", cs: "Vždy, ak používame Meta Ads.", hu: "Vždy, ak používame Meta Ads.", en: "Always, if we use Meta Ads.", de: "Vždy, ak používame Meta Ads." },
  'tools.t2.4what':                  { sk: "Conversion API doplňuje pixel. Bez nej strácate ~30 % konverzií v atribúcii.", cs: "Conversion API doplňuje pixel. Bez nej strácate ~30 % konverzií v atribúcii.", hu: "Conversion API doplňuje pixel. Bez nej strácate ~30 % konverzií v atribúcii.", en: "Conversion API complements the pixel. Without it you lose ~30% of conversions in attribution.", de: "Conversion API doplňuje pixel. Bez nej strácate ~30 % konverzií v atribúcii." },
  'tools.t2.5when':                  { sk: "Pre Pro+ klientov.", cs: "Pro Pro+ klienty.", hu: "Pre Pro+ klientov.", en: "For Pro+ clients.", de: "Pre Pro+ klientov." },
