  'tools.t2.6when':                  { sk: "Pri webe s nízkou konverziou.", cs: "Při webu s nízkou konverzí.", hu: "Pri webe s nízkou konverziou.", en: "For websites with low conversion.", de: "Pri webe s nízkou konverziou." },
  'tools.t2.6what':                  { sk: "Heatmapy a nahrávky relácií — vidíme, čo robia návštevníci a kde „padajú\".", cs: "Heatmapy a nahrávky relací — vidíme, co dělají návštěvníci a kde „padají\".", hu: "Heatmapy a nahrávky relácií — vidíme, čo robia návštevníci a kde „padajú\".", en: "Heatmaps and session recordings — we see what visitors do and where they \"drop off\".", de: "Heatmapy a nahrávky relácií — vidíme, čo robia návštevníci a kde „padajú\"." },
  'tools.cat3Title':                 { sk: "E-mail a automatizácie", cs: "E-mail a automatizace", hu: "E-mail a automatizácie", en: "Email and automation", de: "E-mail a automatizácie" },
  'tools.cat3Desc':                  { sk: "Existujúci zákazník je 5× lacnejší než nový. E-mail to využíva.", cs: "Existující zákazník je 5× levnější než nový. E-mail to využívá.", hu: "Existujúci zákazník je 5× lacnejší než nový. E-mail to využíva.", en: "An existing customer is 5× cheaper than a new one. Email leverages this.", de: "Existujúci zákazník je 5× lacnejší než nový. E-mail to využíva." },
