  'tools.t3.1what':                  { sk: "Jednoduchý newsletter + základné automatizácie. Lacné a rýchle nasadenie.", cs: "Jednoduchý newsletter + základní automatizace. Levné a rychlé nasazení.", hu: "Jednoduchý newsletter + základné automatizácie. Lacné a rýchle nasadenie.", en: "Simple newsletter + basic automations. Cheap and quick deployment.", de: "Jednoduchý newsletter + základné automatizácie. Lacné a rýchle nasadenie." },
  'tools.t3.2when':                  { sk: "Pre rastúce e-shopy.", cs: "Pro rostoucí e-shopy.", hu: "Pre rastúce e-shopy.", en: "For growing e-shops.", de: "Pre rastúce e-shopy." },
  'tools.t3.2what':                  { sk: "Najlepšia integrácia so Shopify/WooCommerce. Welcome flow, abandoned cart, post-purchase.", cs: "Nejlepší integrace se Shopify/WooCommerce. Welcome flow, abandoned cart, post-purchase.", hu: "Najlepšia integrácia so Shopify/WooCommerce. Welcome flow, abandoned cart, post-purchase.", en: "Best integration with Shopify/WooCommerce. Welcome flow, abandoned cart, post-purchase.", de: "Najlepšia integrácia so Shopify/WooCommerce. Welcome flow, abandoned cart, post-purchase." },
  'tools.t3.3when':                  { sk: "Pre B2B a transakčné e-maily.", cs: "Pro B2B a transakční e-maily.", hu: "Pre B2B a transakčné e-maily.", en: "For B2B and transactional emails.", de: "Pre B2B a transakčné e-maily." },
  'tools.t3.3what':                  { sk: "Lacný transakčný e-mail + WhatsApp + SMS v jednom. Dobrá deliverabilita v EÚ.", cs: "Levný transakční e-mail + WhatsApp + SMS v jednom. Dobrá doručitelnost v EU.", hu: "Lacný transakčný e-mail + WhatsApp + SMS v jednom. Dobrá deliverabilita v EÚ.", en: "Cheap transactional email + WhatsApp + SMS in one. Good deliverability in the EU.", de: "Lacný transakčný e-mail + WhatsApp + SMS v jednom. Dobrá deliverabilita v EÚ." },
  'tools.t3.4when':                  { sk: "Keď treba prepojiť 3+ nástroje.", cs: "Když třeba propojit 3+ nástroje.", hu: "Keď treba prepojiť 3+ nástroje.", en: "When you need to connect 3+ tools.", de: "Keď treba prepojiť 3+ nástroje." },
