  'contact.auditCtaNote':            { sk: "Bez záväzku · Odpoveď do ~4 hod", cs: "Bez závazku · Odpověď do ~4 hod", hu: "Kötelezettség nélkül · Válasz ~4 órán belül", en: "No obligation · Response within ~4 hours", de: "Unverbindlich · Antwort in ~4 Std" },
  'contact.audit1Title':             { sk: "Kontrolu reklamných účtov", cs: "Kontrolu reklamních účtů", hu: "Hirdetési fiókok ellenőrzése", en: "Ad Account Review", de: "Überprüfung der Werbekonten" },
  'contact.audit1Desc':              { sk: "Pozrieme Google Ads, Meta, prípadne LinkedIn alebo TikTok účty. Hľadáme, kde sa míňa zbytočne.", cs: "Podíváme se na Google Ads, Meta, případně LinkedIn nebo TikTok účty. Hledáme, kde se zbytečně utrácí.", hu: "Átnézzük a Google Ads, Meta, esetleg LinkedIn vagy TikTok fiókokat. Megkeressük, hol költenek feleslegesen.", en: "We'll examine your Google Ads, Meta, LinkedIn or TikTok accounts. We look for where you're wasting money unnecessarily.", de: "Wir analysieren Ihre Google Ads, Meta sowie LinkedIn oder TikTok Konten. Wir suchen, wo unnötig Budget verschwendet wird." },
  'contact.audit2Title':             { sk: "Audit merania", cs: "Audit měření", hu: "Mérési audit", en: "Tracking Audit", de: "Tracking-Audit" },
  'contact.audit2Desc':              { sk: "Skontrolujeme GA4, Tag Manager, Meta Pixel. Či sa konverzie merajú správne, či sa stráca dáta.", cs: "Zkontrolujeme GA4, Tag Manager, Meta Pixel. Zda se konverze měří správně, zda se neztrácí data.", hu: "Ellenőrizzük a GA4-et, Tag Managert, Meta Pixelt. Hogy a konverziók helyesen mérődnek-e, elvesznek-e adatok.", en: "We'll check GA4, Tag Manager, Meta Pixel. Whether conversions are measured correctly, whether data is being lost.", de: "Wir überprüfen GA4, Tag Manager, Meta Pixel. Ob Conversions korrekt gemessen werden und keine Daten verloren gehen." },
  'contact.audit3Title':             { sk: "Návrh zlepšení", cs: "Návrh zlepšení", hu: "Fejlesztési javaslat", en: "Improvement Recommendations", de: "Verbesserungsvorschläge" },
  'contact.audit3Desc':              { sk: "Konkrétne kroky čo zmeniť — od najľahších quick winov po dlhodobé strategické zmeny.", cs: "Konkrétní kroky co změnit — od nejsnazších quick winů po dlouhodobé strategické změny.", hu: "Konkrét lépések, hogy mit változtassanak — a legkönnyebb gyors győzelmektől a hosszú távú stratégiai változásokig.", en: "Specific steps on what to change — from the easiest quick wins to long-term strategic changes.", de: "Konkrete Schritte für Optimierungen — von einfachen Quick Wins bis hin zu langfristigen strategischen Änderungen." },
  'contact.audit4Title':             { sk: "Plán ďalších 90 dní", cs: "Plán dalších 90 dní", hu: "A következő 90 nap terve", en: "Next 90-Day Plan", de: "90-Tage-Plan" },
  'contact.audit4Desc':              { sk: "Ak by ste chceli pokračovať s nami, vidíte, čo by sme robili a v akom poradí.", cs: "Pokud byste chtěli pokračovat s námi, uvidíte, co bychom dělali a v jakém pořadí.", hu: "Ha velünk folytatnák, látják, mit csinálnánk és milyen sorrendben.", en: "If you'd like to continue with us, you'll see what we would do and in what order.", de: "Falls Sie mit uns weitermachen möchten, sehen Sie, was wir tun würden und in welcher Reihenfolge." },
