  'contact.thanksText1Bold':         { sk: "do ~4 hodín", cs: "do ~4 hodin", hu: "~4 órán belül", en: "within ~4 hours", de: "innerhalb von ~4 Stunden" },
  'contact.thanksText1Suffix':       { sk: "počas pracovných dní (Po–Pi 9–18).", cs: "během pracovních dnů (Po–Pá 9–18).", hu: "munkanapokon (Hé–P 9–18).", en: "during business days (Mon–Fri 9–18).", de: "während der Arbeitszeiten (Mo–Fr 9–18)." },
  'contact.thanksText2':             { sk: "Na váš e-mail sme poslali potvrdenie. Skontrolujte si schránku (prípadne spam).", cs: "Na váš e-mail jsme poslali potvrzení. Zkontrolujte si schránku (případně spam).", hu: "E-mail címére elküldtük a megerősítést. Kérjük, ellenőrizze postafiókját (esetleg a spam mappát is).", en: "We have sent a confirmation to your email. Please check your inbox (and spam folder).", de: "Wir haben Ihnen eine Bestätigung an Ihre E-Mail gesendet. Überprüfen Sie Ihr Postfach (eventuell auch Spam)." },
