  // ============ BLOG PAGE ============
  'blog.introHighlight':             { sk: "Žiadne marketingové fluffy posty.", cs: "Žádné marketingové fluffy posty.", hu: "Semmi marketinges fluff poszt.", en: "No marketing fluff posts.", de: "Keine Marketing-Fluffy-Posts." },
  'blog.introRest':                  { sk: "Píšeme len o tom, čo robíme každý deň - konkrétne kampane, presné čísla, návody, ktoré niekomu reálne pomohli. Bez clickbait nadpisov a bez generic 10 tipov.", cs: "Píšeme jen o tom, co děláme každý den - konkrétní kampaně, přesná čísla, návody, které někomu reálně pomohly. Bez clickbait nadpisů a bez generic 10 tipů.", hu: "Csak arról írunk, amit minden nap csinálunk - konkrét kampányok, pontos számok, útmutatók, amik tényleg segítettek valakinek. Clickbait címek és általános 10 tipp nélkül.", en: "We only write about what we do every day - specific campaigns, precise numbers, guides that have actually helped someone. No clickbait headlines and no generic 10 tips.", de: "Wir schreiben nur über das, was wir täglich machen - konkrete Kampagnen, präzise Zahlen, Anleitungen, die jemandem wirklich geholfen haben. Ohne Clickbait-Überschriften und ohne generische 10 Tipps." },
  'blog.emptyTitle':                 { sk: "Pripravujeme prvé články.", cs: "Připravujeme první články.", hu: "Készítjük az első cikkeket.", en: "We're preparing our first articles.", de: "Wir bereiten die ersten Artikel vor." },
  'blog.emptyLead':                  { sk: "Pracujeme na sérii praktických článkov - od Google Ads cez meranie po automatizácie. Medzitým si môžete prejsť naše služby alebo nás kontaktovať s konkrétnou otázkou.", cs: "Pracujeme na sérii praktických článků - od Google Ads přes měření po automatizace. Mezitím si můžete projít naše služby nebo nás kontaktovat s konkrétní otázkou.", hu: "Gyakorlati cikkek sorozatán dolgozunk - Google Ads-től a mérésig és az automatizálásokig. Addig is átnézhetik szolgáltatásainkat vagy konkrét kérdéssel kereshetnek minket.", en: "We're working on a series of practical articles - from Google Ads through measurement to automations. In the meantime, you can check out our services or contact us with a specific question.", de: "Wir arbeiten an einer Serie praktischer Artikel - von Google Ads über Messung bis zu Automatisierungen. In der Zwischenzeit können Sie sich unsere Dienste ansehen oder uns mit einer konkreten Frage kontaktieren." },
  'blog.emptyServices':              { sk: "Pozrieť služby", cs: "Podívat se na služby", hu: "Szolgáltatások megtekintése", en: "View services", de: "Dienste ansehen" },
  'blog.emptyContact':               { sk: "Mám otázku", cs: "Mám otázku", hu: "Van kérdésem", en: "I have a question", de: "Ich habe eine Frage" },
  'blog.authorRole':                 { sk: "Autor článku", cs: "Autor článku", hu: "A cikk szerzője", en: "Article author", de: "Autor des Artikels" },
  'blog.read':                       { sk: "Čítať", cs: "Číst", hu: "Olvasás", en: "Read", de: "Lesen" },
  'blog.minSuffix':                  { sk: "min", cs: "min", hu: "perc", en: "min", de: "Min" },
  'blog.newsletterTitle':            { sk: "Nový článok raz za 2 týždne.", cs: "Nový článek jednou za 2 týdny.", hu: "Új cikk 2 hetente egyszer.", en: "New article every 2 weeks.", de: "Alle 2 Wochen ein neuer Artikel." },
  'blog.newsletterAccent':           { sk: "Bez spamu.", cs: "Bez spamu.", hu: "Spam nélkül.", en: "No spam.", de: "Ohne Spam." },
  'blog.newsletterLead':             { sk: "Pracovné nálezy, mini case studies a veci, ktoré nás prekvapili. Odhlásiť sa dá jedným klikom.", cs: "Pracovní nálezy, mini case studies a věci, které nás překvapily. Odhlásit se dá jedním klikem.", hu: "Munkahelyi felfedezések, mini case study-k és dolgok, amik megleptek minket. Egy kattintással lehet leiratkozni.", en: "Work findings, mini case studies and things that surprised us. You can unsubscribe with one click.", de: "Arbeitsergebnisse, Mini-Case-Studies und Dinge, die uns überrascht haben. Abmelden mit einem Klick möglich." },
  'blog.newsletterPlaceholder':      { sk: "meno@firma.sk", cs: "jmeno@firma.cz", hu: "nev@ceg.hu", en: "name@company.com", de: "name@firma.de" },
  'blog.newsletterButton':           { sk: "Prihlásiť", cs: "Přihlásit", hu: "Feliratkozás", en: "Subscribe", de: "Anmelden" },
  'blog.newsletterSuccess':          { sk: "Ďakujeme! Prihlásili sme {email} do newslettra.", cs: "Děkujeme! Přihlásili jsme {email} do newsletteru.", hu: "Köszönjük! Feliratkoztattuk {email} címet a newsletterre.", en: "Thank you! We've subscribed {email} to our newsletter.", de: "Vielen Dank! Wir haben {email} für den Newsletter angemeldet." },


  // ============ CASES + LEGAL PAGES ============
  'cases.introHighlight':            { sk: "Prečo zverejňujeme reálne čísla?", cs: "Proč zveřejňujeme reálná čísla?", hu: "Miért tesszük közzé a valós számokat?", en: "Why do we publish real numbers?", de: "Warum veröffentlichen wir echte Zahlen?" },
  'cases.introRest':                 { sk: "Lebo veríme, že vidieť konkrétny príklad povie viac než desať odhadov a sľubov. Každá štúdia obsahuje konkrétne metriky, obdobie, kanály a popis toho, čo sme robili. Mená klientov zverejňujeme len s ich súhlasom.", cs: "Protože věříme, že konkrétní příklad řekne více než deset odhadů a slibů. Každá studie obsahuje konkrétní metriky, období, kanály a popis toho, co jsme dělali. Jména klientů zveřejňujeme pouze s jejich souhlasem.", hu: "Mert hisszük, hogy egy konkrét példa többet mond, mint tíz becslés és ígéret. Minden tanulmány tartalmaz konkrét mutatókat, időszakot, csatornákat és leírást arról, hogy mit csináltunk. Az ügyfelek neveit csak hozzájárulásukkal tesszük közzé.", en: "Because we believe that seeing a concrete example says more than ten estimates and promises. Each case study contains specific metrics, time period, channels and description of what we did. We publish client names only with their consent.", de: "Weil wir glauben, dass ein konkretes Beispiel mehr aussagt als zehn Schätzungen und Versprechen. Jede Studie enthält konkrete Metriken, Zeiträume, Kanäle und eine Beschreibung dessen, was wir getan haben. Kundennamen veröffentlichen wir nur mit deren Zustimmung." },
  'cases.emptyTitle':                { sk: "Pripravujeme prvé verejné štúdie.", cs: "Připravujeme první veřejné studie.", hu: "Az első nyilvános tanulmányokat készítjük elő.", en: "We are preparing the first public case studies.", de: "Wir bereiten die ersten öffentlichen Studien vor." },
  'cases.emptyLead':                 { sk: "Niekoľko klientov je v procese odsúhlasovania zverejnenia výsledkov. Medzitým vám čísla radi ukážeme priamo na stretnutí - anonymizované alebo so súhlasom toho-ktorého klienta.", cs: "Několik klientů je v procesu odsouhlasování zveřejnění výsledků. Mezitím Vám čísla rádi ukážeme přímo na jednání - anonymizovaná nebo se souhlasem příslušného klienta.", hu: "Több ügyfél van az eredmények közzétételének jóváhagyási folyamatában. Addig szívesen mutatjuk meg Önöknek a számokat személyesen egy találkozón - anonimizáltan vagy az adott ügyfél hozzájárulásával.", en: "Several clients are in the process of approving the publication of results. In the meantime, we are happy to show you the numbers directly at a meeting - anonymized or with the consent of the respective client.", de: "Mehrere Kunden befinden sich im Prozess der Genehmigung zur Veröffentlichung der Ergebnisse. In der Zwischenzeit zeigen wir Ihnen die Zahlen gerne direkt in einem Gespräch - anonymisiert oder mit Zustimmung des jeweiligen Kunden." },
  'cases.emptyCta':                  { sk: "Spýtať sa na referencie", cs: "Zeptat se na reference", hu: "Referenciákat kérni", en: "Ask for references", de: "Nach Referenzen fragen" },
