  // ============ COOKIES BODY ============
  'cookies.s1Title':                 { sk: "1. Čo sú cookies", cs: "1. Co jsou cookies", hu: "1. Mik azok a sütik (cookies)", en: "1. What are cookies", de: "1. Was sind Cookies" },
  'cookies.s1Body':                  { sk: "Cookies sú malé textové súbory, ktoré sa pri návšteve webu uložia do vášho prehliadača. Pomáhajú webu fungovať lepšie, zapamätať si vaše preferencie a v niektorých prípadoch sledovať, ako web používate (na účely analytiky alebo reklamy).", cs: "Cookies jsou malé textové soubory, které se při návštěvě webu uloží do Vašeho prohlížeče. Pomáhají webu fungovat lépe, zapamatovat si Vaše preference a v některých případech sledovat, jak web používáte (pro účely analytiky nebo reklamy).", hu: "A sütik (cookies) olyan kis szöveges fájlok, amelyek a weboldal látogatásakor az Ön böngészőjében tárolódnak. Segítenek a weboldalnak jobban működni, megjegyezni az Ön preferenciáit, és bizonyos esetekben nyomon követni, hogyan használja a weboldalt (analitikai vagy reklám célokra).", en: "Cookies are small text files that are stored in your browser when you visit a website. They help the website function better, remember your preferences, and in some cases track how you use the website (for analytics or advertising purposes).", de: "Cookies sind kleine Textdateien, die beim Besuch einer Website in Ihrem Browser gespeichert werden. Sie helfen der Website, besser zu funktionieren, sich Ihre Präferenzen zu merken und in einigen Fällen zu verfolgen, wie Sie die Website nutzen (für Analyse- oder Werbezwecke)." },
  'cookies.s2Title':                 { sk: "2. Aké cookies používame", cs: "2. Jaké cookies používáme", hu: "2. Milyen sütiket használunk", en: "2. What cookies we use", de: "2. Welche Cookies wir verwenden" },
  'cookies.s2aHeading':              { sk: "A) Nevyhnutné cookies (vždy aktívne)", cs: "A) Nezbytné cookies (vždy aktivní)", hu: "A) Szükséges sütik (mindig aktívak)", en: "A) Essential cookies (always active)", de: "A) Notwendige Cookies (immer aktiv)" },
  'cookies.s2aBody':                 { sk: "Bez týchto web nemôže fungovať. Nevyžadujú váš súhlas.", cs: "Bez těchto web nemůže fungovat. Nevyžadují Váš souhlas.", hu: "Ezek nélkül a weboldal nem tud működni. Nem igénylik az Ön hozzájárulását.", en: "Without these, the website cannot function. They do not require your consent.", de: "Ohne diese kann die Website nicht funktionieren. Sie erfordern nicht Ihre Zustimmung." },
  'cookies.s2bHeading':              { sk: "B) Analytické cookies (vyžadujú súhlas)", cs: "B) Analytické cookies (vyžadují souhlas)", hu: "B) Analitikai sütik (hozzájárulást igényelnek)", en: "B) Analytical cookies (require consent)", de: "B) Analytische Cookies (erfordern Zustimmung)" },
  'cookies.s2bBody':                 { sk: "Pomáhajú nám pochopiť, ako návštevníci používajú web. Nikoho neidentifikujú osobne.", cs: "Pomáhají nám pochopit, jak návštěvníci používají web. Nikoho neidentifikují osobně.", hu: "Segítenek megérteni, hogyan használják a látogatók a weboldalt. Személyesen senkit sem azonosítanak.", en: "They help us understand how visitors use the website. They do not identify anyone personally.", de: "Sie helfen uns zu verstehen, wie Besucher die Website nutzen. Sie identifizieren niemanden persönlich." },
  'cookies.s2cHeading':              { sk: "C) Marketingové cookies (vyžadujú súhlas)", cs: "C) Marketingové cookies (vyžadují souhlas)", hu: "C) Marketing sütik (hozzájárulást igényelnek)", en: "C) Marketing cookies (require consent)", de: "C) Marketing-Cookies (erfordern Zustimmung)" },
  'cookies.s2cBody':                 { sk: "Slúžia na zobrazovanie relevantných reklám na iných weboch a meranie ich účinnosti.", cs: "Slouží k zobrazování relevantních reklam na jiných webech a měření jejich účinnosti.", hu: "Releváns reklámok megjelenítésére szolgálnak más weboldalakon és azok hatékonyságának mérésére.", en: "They serve to display relevant advertisements on other websites and measure their effectiveness.", de: "Sie dienen der Anzeige relevanter Werbung auf anderen Websites und der Messung ihrer Wirksamkeit." },
