  'cookies.row7Dur':                 { sk: "3 mesiace", cs: "3 měsíce", hu: "3 hónap", en: "3 months", de: "3 Monate" },
  'cookies.s3Title':                 { sk: "3. Ako spravovať svoj súhlas", cs: "3. Jak spravovat Váš souhlas", hu: "3. Hogyan kezelje hozzájárulását", en: "3. How to manage your consent", de: "3. Wie Sie Ihre Einwilligung verwalten" },
  'cookies.s3Body1':                 { sk: "Pri prvej návšteve sa zobrazuje cookie banner, kde môžete jednotlivé kategórie cookies prijať alebo odmietnuť. Svoje rozhodnutie môžete kedykoľvek zmeniť:", cs: "Při první návštěvě se zobrazuje cookie banner, kde můžete jednotlivé kategorie cookies přijmout nebo odmítnout. Své rozhodnutí můžete kdykoli změnit:", hu: "Az első látogatás alkalmával megjelenik a cookie banner, ahol az egyes cookie kategóriákat elfogadhatja vagy elutasíthatja. Döntését bármikor megváltoztathatja:", en: "When you first visit, a cookie banner appears where you can accept or reject individual cookie categories. You can change your decision at any time:", de: "Bei Ihrem ersten Besuch wird ein Cookie-Banner angezeigt, in dem Sie einzelne Cookie-Kategorien akzeptieren oder ablehnen können. Sie können Ihre Entscheidung jederzeit ändern:" },
  'cookies.s3Bullet1':               { sk: "Klinutím na", cs: "Kliknutím na", hu: "A", en: "By clicking on", de: "Durch Klick auf" },
  'cookies.s3BulletLink':            { sk: "Spravovať cookies", cs: "Spravovat cookies", hu: "Cookies kezelése", en: "Manage cookies", de: "Cookies verwalten" },
  'cookies.s3Bullet1End':            { sk: "(otvorí banner znova)", cs: "(otevře banner znovu)", hu: "gombra kattintva (újra megnyitja a bannert)", en: "(opens banner again)", de: "(öffnet den Banner erneut)" },
  'cookies.s3Bullet2':               { sk: "Vymazaním cookies vo vašom prehliadači", cs: "Vymazáním cookies ve Vašem prohlížeči", hu: "A böngészőjében lévő cookies törlésével", en: "By clearing cookies in your browser", de: "Durch Löschen der Cookies in Ihrem Browser" },
  'cookies.s3Body2':                 { sk: "Cookies môžete spravovať aj priamo v nastaveniach prehliadača:", cs: "Cookies můžete spravovat také přímo v nastavení prohlížeče:", hu: "A cookie-kat közvetlenül a böngésző beállításaiban is kezelheti:", en: "You can also manage cookies directly in your browser settings:", de: "Cookies können Sie auch direkt in den Browser-Einstellungen verwalten:" },
  'cookies.s4Title':                 { sk: "4. Dôsledky odmietnutia", cs: "4. Důsledky odmítnutí", hu: "4. Az elutasítás következményei", en: "4. Consequences of rejection", de: "4. Folgen der Ablehnung" },
  'cookies.s4Body':                  { sk: "Ak odmietnete analytické a marketingové cookies, web bude fungovať bez problémov. Strácame iba prehľad o tom, ako návštevníci web používajú, a nemôžeme zobrazovať relevantné reklamy. Nevyhnutné cookies sa neukladajú vôbec, ak nesúhlasíte.", cs: "Pokud odmítnete analytické a marketingové cookies, web bude fungovat bez problémů. Ztrácíme pouze přehled o tom, jak návštěvníci web používají, a nemůžeme zobrazovat relevantní reklamy. Nezbytné cookies se neukládají vůbec, pokud nesouhlasíte.", hu: "Ha elutasítja az analitikai és marketing cookie-kat, a weboldal problémamentesen fog működni. Csak azt az áttekintést veszítjük el, hogy a látogatók hogyan használják a weboldalt, és nem tudunk releváns hirdetéseket megjeleníteni. A szükséges cookie-k egyáltalán nem kerülnek tárolásra, ha nem járul hozzá.", en: "If you reject analytical and marketing cookies, the website will function without problems. We only lose insight into how visitors use the website and cannot display relevant advertisements. Essential cookies are not stored at all if you do not consent.", de: "Wenn Sie analytische und Marketing-Cookies ablehnen, funktioniert die Website problemlos. Wir verlieren lediglich den Überblick darüber, wie Besucher die Website nutzen, und können keine relevante Werbung anzeigen. Erforderliche Cookies werden überhaupt nicht gespeichert, wenn Sie nicht zustimmen." },
  'cookies.s5Title':                 { sk: "5. Ďalšie informácie", cs: "5. Další informace", hu: "5. További információk", en: "5. Additional Information", de: "5. Weitere Informationen" },
  'cookies.s5BodyPrefix':            { sk: "Bližšie informácie o spracovaní osobných údajov nájdete v", cs: "Bližší informace o zpracování osobních údajů najdete v", hu: "A személyes adatok kezelésével kapcsolatos további információkat megtalálja a", en: "More detailed information about personal data processing can be found in our", de: "Nähere Informationen zur Verarbeitung personenbezogener Daten finden Sie in unserem" },
  'cookies.s5BodyLink':              { sk: "Ochrane osobných údajov", cs: "Ochraně osobních údajů", hu: "Adatvédelemben", en: "Privacy Policy", de: "Datenschutz" },
  'cookies.toc1':                    { sk: "Čo sú cookies", cs: "Co jsou cookies", hu: "Mit jelentenek a sütik", en: "What are cookies", de: "Was sind Cookies" },
  'cookies.toc2':                    { sk: "Aké cookies používame", cs: "Jaké cookies používáme", hu: "Milyen sütiket használunk", en: "What cookies we use", de: "Welche Cookies wir verwenden" },
  'cookies.toc3':                    { sk: "Ako spravovať súhlas", cs: "Jak spravovat souhlas", hu: "Hogyan kezelje a hozzájárulást", en: "How to manage consent", de: "Wie Sie die Einwilligung verwalten" },
  'cookies.toc4':                    { sk: "Dôsledky odmietnutia", cs: "Důsledky odmítnutí", hu: "Az elutasítás következményei", en: "Consequences of rejection", de: "Folgen der Ablehnung" },
