  // ============ PRIVACY BODY ============
  'privacy.lead':                    { sk: "Ako spracúvame, chránime a používame vaše osobné údaje v súlade s GDPR a slovenskou legislatívou.", cs: "Jak zpracováváme, chráníme a používáme vaše osobní údaje v souladu s GDPR a českou legislativou.", hu: "Hogyan dolgozzuk fel, védjük és használjuk az Önök személyes adatait a GDPR és a szlovákiai jogszabályok szerint.", en: "How we process, protect and use your personal data in compliance with GDPR and Slovak legislation.", de: "Wie wir Ihre personenbezogenen Daten in Übereinstimmung mit der DSGVO und der slowakischen Gesetzgebung verarbeiten, schützen und verwenden." },
  'privacy.s1Title':                 { sk: "1. Prevádzkovateľ", cs: "1. Správce", hu: "1. Adatkezelő", en: "1. Controller", de: "1. Verantwortlicher" },
  'privacy.s1Intro':                 { sk: "Prevádzkovateľom v zmysle GDPR (Nariadenie EÚ 2016/679) a zákona č. 18/2018 Z. z. o ochrane osobných údajov je:", cs: "Správcem ve smyslu GDPR (Nařízení EU 2016/679) a zákona č. 110/2019 Sb. o zpracování osobních údajů je:", hu: "A GDPR (EU rendelet 2016/679) és a 18/2018. sz. személyes adatok védelméről szóló törvény értelmében az adatkezelő:", en: "The controller within the meaning of GDPR (EU Regulation 2016/679) and Act No. 18/2018 Coll. on the protection of personal data is:", de: "Verantwortlicher im Sinne der DSGVO (Verordnung EU 2016/679) und des Gesetzes Nr. 18/2018 Slg. über den Schutz personenbezogener Daten ist:" },
  'privacy.s1IcoLabel':              { sk: "IČO", cs: "IČO", hu: "Cégjegyzékszám", en: "ID No.", de: "Firmennummer" },
  'privacy.s1AddressLabel':          { sk: "Sídlo", cs: "Sídlo", hu: "Székhely", en: "Registered Office", de: "Sitz" },
  'privacy.s1ContactLabel':          { sk: "Kontakt", cs: "Kontakt", hu: "Kapcsolat", en: "Contact", de: "Kontakt" },
  'privacy.s1DpoNote':               { sk: "Vzhľadom na rozsah činnosti nemáme povinnosť vymenovať Zodpovednú osobu (DPO). V prípade akýchkoľvek otázok ohľadne osobných údajov nás kontaktujte na uvedenom e-maile.", cs: "Vzhledem k rozsahu činnosti nemáme povinnost jmenovat Pověřenou osobu (DPO). V případě jakýchkoliv otázek ohledně osobních údajů nás kontaktujte na uvedeném e-mailu.", hu: "Tevékenységünk jellege miatt nincs kötelezettségünk adatvédelmi tisztviselő (DPO) kinevezésére. Személyes adatokkal kapcsolatos bármilyen kérdés esetén kérjük, lépjenek kapcsolatba velünk a megadott e-mail címen.", en: "Given the scope of our activities, we are not obligated to appoint a Data Protection Officer (DPO). For any questions regarding personal data, please contact us at the provided email address.", de: "Aufgrund des Umfangs unserer Tätigkeit sind wir nicht verpflichtet, einen Datenschutzbeauftragten (DSB) zu bestellen. Bei Fragen bezüglich personenbezogener Daten kontaktieren Sie uns unter der angegebenen E-Mail-Adresse." },
  'privacy.s2Title':                 { sk: "2. Aké údaje spracúvame", cs: "2. Jaké údaje zpracováváme", hu: "2. Milyen adatokat dolgozunk fel", en: "2. What data we process", de: "2. Welche Daten wir verarbeiten" },
  'privacy.s2aTitle':                { sk: "A) Údaje z kontaktného formulára", cs: "A) Údaje z kontaktního formuláře", hu: "A) Kapcsolatfelvételi űrlapból származó adatok", en: "A) Data from contact form", de: "A) Daten aus dem Kontaktformular" },
