  'privacy.s2aItem3':                { sk: "Názov firmy / web (voliteľné)", cs: "Název firmy / web (volitelné)", hu: "Cégnév / weboldal (opcionális)", en: "Company name / website (optional)", de: "Firmenname / Website (optional)" },
