  'privacy.s2bLegal':                { sk: "Váš súhlas (čl. 6 ods. 1 písm. a GDPR).", cs: "Váš souhlas (čl. 6 odst. 1 písm. a GDPR).", hu: "Az Ön hozzájárulása (GDPR 6. cikk (1) bekezdés a) pont).", en: "Your consent (Art. 6(1)(a) GDPR).", de: "Ihre Einwilligung (Art. 6 Abs. 1 lit. a DSGVO)." },
  'privacy.s2bRetention':            { sk: "do odvolania súhlasu (odhlásenie cez link v každom e-maile).", cs: "do odvolání souhlasu (odhlášení přes odkaz v každém e-mailu).", hu: "a hozzájárulás visszavonásáig (leiratkozás minden e-mailben található linken keresztül).", en: "until consent is withdrawn (unsubscribe via link in each email).", de: "bis zum Widerruf der Einwilligung (Abmeldung über Link in jeder E-Mail)." },
  'privacy.s2cTitle':                { sk: "C) Údaje zo zmluvných vzťahov", cs: "C) Údaje ze smluvních vztahů", hu: "C) Szerződéses jogviszonyokból származó adatok", en: "C) Data from contractual relationships", de: "C) Daten aus Vertragsverhältnissen" },
