  'privacy.s2cItem3':                { sk: "Komunikácia v rámci projektu", cs: "Komunikace v rámci projektu", hu: "Projekten belüli kommunikáció", en: "Communication within the project", de: "Kommunikation im Rahmen des Projekts" },
  'privacy.s2cPurpose':              { sk: "plnenie zmluvy, fakturácia, právna ochrana.", cs: "plnění smlouvy, fakturace, právní ochrana.", hu: "szerződés teljesítése, számlázás, jogvédelem.", en: "contract performance, invoicing, legal protection.", de: "Vertragserfüllung, Rechnungsstellung, Rechtsschutz." },
  'privacy.s2cLegal':                { sk: "Plnenie zmluvy (čl. 6 ods. 1 písm. b GDPR), zákonná povinnosť (čl. 6 ods. 1 písm. c - daňové a účtovné zákony).", cs: "Plnění smlouvy (čl. 6 odst. 1 písm. b GDPR), zákonná povinnost (čl. 6 odst. 1 písm. c - daňové a účetní zákony).", hu: "Szerződés teljesítése (GDPR 6. cikk (1) bekezdés b) pont), jogi kötelezettség (GDPR 6. cikk (1) bekezdés c) pont - adó- és számviteli törvények).", en: "Performance of contract (Art. 6(1)(b) GDPR), legal obligation (Art. 6(1)(c) - tax and accounting laws).", de: "Vertragserfüllung (Art. 6 Abs. 1 lit. b DSGVO), gesetzliche Verpflichtung (Art. 6 Abs. 1 lit. c DSGVO - Steuer- und Buchführungsgesetze)." },
  'privacy.s2cRetention':            { sk: "10 rokov (zákonná povinnosť pre účtovnú dokumentáciu).", cs: "10 let (zákonná povinnost pro účetní dokumentaci).", hu: "10 év (törvényi kötelezettség a számviteli dokumentáció számára).", en: "10 years (legal obligation for accounting documentation).", de: "10 Jahre (gesetzliche Verpflichtung für Buchhaltungsunterlagen)." },
  'privacy.s2dTitle':                { sk: "D) Údaje z analytických nástrojov", cs: "D) Údaje z analytických nástrojů", hu: "D) Analitikai eszközökből származó adatok", en: "D) Data from analytical tools", de: "D) Daten aus Analysetools" },
  'privacy.s2dBodyPrefix':           { sk: "Pri návšteve webu zbierame anonymizované údaje o správaní (pozri stránku", cs: "Při návštěvě webu shromažďujeme anonymizované údaje o chování (viz stránka", hu: "A webhely meglátogatásakor anonim viselkedési adatokat gyűjtünk (lásd", en: "When visiting the website, we collect anonymized behavioral data (see page", de: "Bei Ihrem Besuch auf der Website sammeln wir anonymisierte Verhaltensdaten (siehe Seite" },
