  'privacy.s3Intro':                 { sk: "Vaše údaje môžu byť odovzdané týmto sprostredkovateľom (vždy s primeranou ochranou):", cs: "Vaše údaje mohou být předány těmto zprostředkovatelům (vždy s přiměřenou ochranou):", hu: "Az Önök adatai továbbíthatók ezen adatfeldolgozóknak (mindig megfelelő védelemmel):", en: "Your data may be transferred to these processors (always with appropriate protection):", de: "Ihre Daten können an diese Auftragsverarbeiter weitergegeben werden (immer mit angemessenem Schutz):" },
