/**
 * Vráti lokalizovaný UI text. Ak kľúč chýba, vráti SK fallback alebo kľúč.
 */
export function t(key: string, lang: Lang): string {
  const entry = DICT[key];
  if (!entry) return key;
  return entry[lang] || entry.sk || key;
}
